package com.aayushpuranik.jokesandmemesapp.coreimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.widthimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.MaterialThemeimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpobject UIUtils {    @Composable    fun IndeterminateCircularIndicator(isLoading: Boolean) {        if (!isLoading) return        Column(            horizontalAlignment = Alignment.CenterHorizontally,            verticalArrangement =  Arrangement.Center,            modifier = Modifier.fillMaxSize()        ) {            CircularProgressIndicator(                modifier = Modifier.width(64.dp),                color = MaterialTheme.colorScheme.secondary,                trackColor = MaterialTheme.colorScheme.surfaceVariant,            )        }    }}